files.content:
.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #565758;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247cff;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #247cff;
  --vt-accent-on-deep: #247cff;
  --vt-line: #eaeaea;

  background: var(--vt-surface);
  color: var(--vt-ink-soft);
  font-family: 'Open Sans', sans-serif;
  padding-top: 94px;
  position: relative;
}

.root h1,
.root h2,
.root h3,
.root h4,
.root h5,
.root h6 {
  font-weight: 700;
  color: var(--vt-ink);
  line-height: 1.2;
  margin: 0 0 0.5rem 0;
}

.root h1 { font-size: 48px; }
.root h2 { font-size: 36px; }
.root h3 { font-size: 32px; }
.root h4 { font-size: 28px; }
.root h5 { font-size: 24px; }
.root h6 { font-size: 22px; }

.root p {
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
  margin: 0 0 1rem 0;
}

.root a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  transition: color 0.3s ease;
}

.root a:hover {
  color: var(--vt-accent);
}

.container {
  width: 100%;
  max-width: 1320px;
  margin: 0 auto;
  padding: 0 15px;
}

.sectionPadding {
  padding-top: 7rem;
  padding-bottom: 7rem;
}

.pb0 { padding-bottom: 0; }

.nav {
  background: var(--vt-surface);
  box-shadow: 0 0 25px rgba(0,0,0,0.15);
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  padding: 20px 0;
}

.navIn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 1320px;
  margin: 0 auto;
  padding: 0 15px;
}

.logo {
  display: flex;
  align-items: center;
}

.brand {
  font-size: 24px;
  font-weight: 700;
  color: var(--vt-accent);
  text-align: center;
}

.navLinks {
  display: flex;
  align-items: center;
}

.navLinks a {
  padding: 15px 1.5rem;
  font-weight: 600;
  font-size: 16px;
  color: var(--vt-ink-soft);
}

.navLinks a:hover {
  color: var(--vt-ink);
}

.hero {
  position: relative;
  overflow: hidden;
}

.heroSlides {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  height: 580px;
}

.heroSlide {
  flex: 0 0 100%;
  scroll-snap-align: start;
  height: 100%;
}

.heroImg {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.heroText {
  position: absolute;
  z-index: 2;
  bottom: 0;
  right: 0;
  background: var(--vt-surface);
  padding: 1.5rem 2.5rem;
  width: 50%;
  box-sizing: border-box;
}

.heroTitle {
  margin-bottom: 0.5rem;
}

.animatedItem {
  color: var(--vt-accent);
}

.heroP {
  margin-bottom: 1rem;
}

.heroLinks {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
}

.customLink {
  display: inline-block;
  text-decoration: none;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: 600;
  line-height: 40px;
  position: relative;
  padding: 0 30px;
  box-sizing: border-box;
  overflow: hidden;
  text-transform: uppercase;
  margin-right: 1rem;
  background: transparent;
  transition: all 0.3s;
}

.customLink::before {
  content: attr(data-hover);
  background-color: var(--vt-line);
  color: var(--vt-accent);
  position: absolute;
  top: 100%;
  bottom: 0;
  left: 0;
  transition: all 300ms cubic-bezier(0.19, 1, 0.56, 1);
  right: 0;
  text-align: center;
}

.customLink:hover::before {
  top: 0;
}

.contactPhone {
  font-weight: 600;
  margin: 0;
}

.phoneIcon {
  margin-right: 0.5rem;
}

.aboutRow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
}

.aboutText {
  flex: 0 0 auto;
  width: 100%;
  max-width: 66.6667%;
  padding: 0 15px;
}

.aboutH2 {
  margin-bottom: 1.5rem;
}

.gallery {
  background: var(--vt-surface-2);
}

.galleryRow {
  display: flex;
  flex-wrap: wrap;
  margin: 0;
}

.galleryItem {
  width: 50%;
  padding: 0;
}

.galleryImg {
  width: 100%;
  height: auto;
  display: block;
}

.timelineHeader {
  text-align: center;
  margin-bottom: 3rem;
}

.timeline {
  position: relative;
}

.timeline::before {
  content: "";
  position: absolute;
  top: 60px;
  left: 50%;
  transform: translateX(-50%);
  width: 0;
  border-left: 1px solid var(--vt-line);
  height: 90%;
  z-index: 1;
}

.timelineNode {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin: 2rem 0;
  position: relative;
}

.timelineNode:nth-child(even) {
  flex-direction: row-reverse;
}

.timelineContent {
  width: 45%;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.15);
  border-radius: 0 0 0.25rem 0.25rem;
  padding: 0;
}

.timelineTitle {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  margin: 0;
  border-radius: 0.25rem 0.25rem 0 0;
  font-size: 1.5rem;
}

.timelineContent p {
  padding: 10px 30px;
  margin: 0;
}

.timelineNode:nth-child(odd) .timelineContent {
  text-align: right;
}

.timelineNode:nth-child(odd) .timelineTitle {
  border-radius: 0.25rem 0.25rem 0 0;
}

.timelineNode:nth-child(odd) .timelineTitle::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translate(0, -50%);
  width: 0;
  border-left: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineNode:nth-child(even) .timelineContent {
  text-align: left;
}

.timelineNode:nth-child(even) .timelineTitle::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translate(0, -50%);
  width: 0;
  border-right: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineIconWrap {
  width: 80px;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  position: relative;
  z-index: 100;
}

.timelineIconWrap::before {
  content: "";
  width: 80px;
  height: 80px;
  border-radius: 50%;
  display: block;
  position: absolute;
  top: 0;
  left: 50%;
  transform: translate(-50%,0);
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem rgba(0,0,0,.175);
  z-index: 1;
}

.timelineIcon {
  position: relative;
  z-index: 100;
  font-size: 2rem;
  color: var(--vt-accent);
  display: block;
  text-align: center;
  line-height: 80px;
}

.timelineDate {
  width: 45%;
  padding: 1rem 0;
}

.timelineNode:nth-child(odd) .timelineDate {
  text-align: left;
}

.timelineNode:nth-child(even) .timelineDate {
  text-align: right;
}

.timelineDate time {
  font-weight: 600;
  color: var(--vt-ink-soft);
}

.siteFooter {
  background: var(--vt-surface-2);
  padding-top: 5rem;
  padding-bottom: 5rem;
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
}

.footerHours,
.footerClinic,
.footerSocial,
.footerCopyright {
  width: 100%;
  max-width: 25%;
  padding: 0 15px;
  box-sizing: border-box;
}

.footerHours h5,
.footerClinic h5,
.footerSocial h5 {
  margin-bottom: 1.5rem;
}

.footerCopyright {
  margin-top: 2rem;
  max-width: 100%;
  text-align: center;
}

.socialLinks {
  display: flex;
  list-style: none;
  padding: 0;
}

.socialLinks li {
  margin-right: 15px;
}

@media (max-width: 991px) {
  .root { padding-top: 74px; }
  .root h1 { font-size: 38px; }
  .root h2 { font-size: 32px; }
  .root h3 { font-size: 26px; }
  .root h5 { font-size: 20px; }
  .sectionPadding { padding-top: 5rem; padding-bottom: 5rem; }
  .heroSlides { height: auto; min-height: 400px; }
  .heroText { position: relative; bottom: auto; right: auto; width: auto; margin-bottom: -100px; padding: 2rem; transform: translateY(-100px); }
  .footerHours, .footerClinic, .footerSocial, .footerCopyright { max-width: 50%; margin-bottom: 2rem; }
  .footerCopyright { max-width: 100%; text-align: center; }
}

@media (max-width: 767px) {
  .galleryItem { width: 100%; }
  .aboutText { max-width: 100%; }
  .timelineNode { flex-direction: column; align-items: stretch; }
  .timelineNode:nth-child(even) { flex-direction: column; }
  .timelineContent, .timelineDate { width: 100%; text-align: left; }
  .timelineNode:nth-child(odd) .timelineContent, .timelineNode:nth-child(even) .timelineContent { text-align: left; }
  .timelineNode:nth-child(odd) .timelineDate, .timelineNode:nth-child(even) .timelineDate { text-align: left; }
  .timeline::before { left: 33px; }
  .timelineIconWrap { position: absolute; left: 0; top: 60px; width: 80px; }
  .timelineContent { padding-left: 100px; }
  .timelineHeader { margin-bottom: 2rem; }
}

@media (max-width: 480px) {
  .root h1 { font-size: 32px; }
  .heroText { padding: 1rem; }
  .customLink { font-size: 12px; line-height: 30px; padding: 0 25px; margin-right: 12px; }
  .contactPhone { font-size: 12px; }
  .timelineIconWrap { left: -10px; }
  .timelineIconWrap::before { width: 70px; height: 70px; }
  .timelineIcon { line-height: 70px; font-size: 1.5rem; }
}
